class Solution {
public:
    int longestIdealString(std::string s, int k) {
        std::vector<int> dp(26, 0);
        for (char ch : s) {
            int idx = ch - 'a';
            int low = std::max(0, idx - k);
            int high = std::min(25, idx + k);
            int mx = 0;
            for (int i = low; i <= high; ++i) mx = std::max(mx, dp[i]);
            dp[idx] = 1 + mx;
        }
        int ans = 0;
        for (int v : dp) ans = std::max(ans, v);
        return ans;
    }
};

class Solution {
    public int longestIdealString(String s, int k) {
        int[] dp = new int[26];
        for (int c = 0; c < s.length(); ++c) {
            int idx = s.charAt(c) - 'a';
            int low = Math.max(0, idx - k);
            int high = Math.min(25, idx + k);
            int mx = 0;
            for (int i = low; i <= high; ++i) mx = Math.max(mx, dp[i]);
            dp[idx] = 1 + mx;
        }
        int ans = 0;
        for (int v : dp) ans = Math.max(ans, v);
        return ans;
    }
}

var longestIdealString = function(s, k) {
    const dp = new Array(26).fill(0);
    for (let c = 0; c < s.length; ++c) {
        const idx = s.charCodeAt(c) - 97;
        const low = Math.max(0, idx - k);
        const high = Math.min(25, idx + k);
        let mx = 0;
        for (let i = low; i <= high; ++i) {
            if (dp[i] > mx) mx = dp[i];
        }
        dp[idx] = 1 + mx;
    }
    return Math.max(...dp);
};
